ALTER TABLE "projects"
ADD COLUMN "homepage_position" SMALLINT;

CREATE UNIQUE INDEX "projects_homepage_position_key"
ON "projects"("homepage_position");

ALTER TABLE "projects"
ADD CONSTRAINT "projects_homepage_position_range"
CHECK ("homepage_position" IS NULL OR "homepage_position" BETWEEN 1 AND 9);

UPDATE "projects"
SET "homepage_position" = CASE "id"
    WHEN '00000000-0000-4000-8000-000000000001' THEN 1
    WHEN '00000000-0000-4000-8000-000000000002' THEN 2
    WHEN '00000000-0000-4000-8000-000000000003' THEN 3
    WHEN '00000000-0000-4000-8000-000000000004' THEN 4
    WHEN '00000000-0000-4000-8000-000000000005' THEN 5
    WHEN '00000000-0000-4000-8000-000000000006' THEN 6
    WHEN '00000000-0000-4000-8000-000000000007' THEN 7
    WHEN '00000000-0000-4000-8000-000000000008' THEN 8
    WHEN '00000000-0000-4000-8000-000000000009' THEN 9
END
WHERE "id" IN (
    '00000000-0000-4000-8000-000000000001',
    '00000000-0000-4000-8000-000000000002',
    '00000000-0000-4000-8000-000000000003',
    '00000000-0000-4000-8000-000000000004',
    '00000000-0000-4000-8000-000000000005',
    '00000000-0000-4000-8000-000000000006',
    '00000000-0000-4000-8000-000000000007',
    '00000000-0000-4000-8000-000000000008',
    '00000000-0000-4000-8000-000000000009'
);
